CREATE VIEW `v_invoice_status_totals` AS
  SELECT
    i.`status` AS `status`,
    COUNT(i.`id`) AS `invoices`,
    CAST(SUM(i.`amountCents`) AS SIGNED) AS `totalCents`,
    CAST(SUM(CASE WHEN i.`status` = 'PAID' THEN i.`amountCents` END) AS SIGNED) AS `paidCents`
  FROM `invoices` i
  GROUP BY i.`status`;

CREATE VIEW `v_invoices_by_month` AS
  SELECT
    DATE(DATE_FORMAT(i.`issuedOn`, '%Y-%m-01')) AS `issuedOnMonth`,
    COUNT(i.`id`) AS `invoices`,
    CAST(SUM(i.`amountCents`) AS SIGNED) AS `totalCents`
  FROM `invoices` i
  GROUP BY DATE(DATE_FORMAT(i.`issuedOn`, '%Y-%m-01'));

CREATE VIEW `v_invoice_totals` AS
  SELECT
    COUNT(i.`id`) AS `invoices`,
    CAST(SUM(i.`amountCents`) AS SIGNED) AS `totalCents`,
    COUNT(CASE WHEN i.`status` = 'PAID' THEN i.`id` END) / NULLIF(COUNT(i.`id`), 0) AS `paidShare`
  FROM `invoices` i;

CREATE VIEW `v_invoice_calendar` AS
  SELECT
    DATE(i.`issuedOn`) AS `issuedOnDay`,
    DATE(DATE_FORMAT(i.`issuedOn`, '%Y-%m-01')) AS `issuedOnMonth`,
    COUNT(i.`id`) AS `invoices`,
    CAST(SUM(i.`amountCents`) AS SIGNED) AS `totalCents`
  FROM `invoices` i
  GROUP BY DATE(i.`issuedOn`), DATE(DATE_FORMAT(i.`issuedOn`, '%Y-%m-01'));

CREATE VIEW `v_invoice_disputes` AS
  SELECT
    i.`disputed` AS `disputed`,
    COUNT(i.`id`) AS `invoices`,
    COUNT(CASE WHEN i.`amountCents` >= 60000 THEN i.`id` END) AS `bigInvoices`
  FROM `invoices` i
  GROUP BY i.`disputed`;

CREATE VIEW `v_product_revenue` AS
  SELECT
    p.`id` AS `productId`,
    p.`name` AS `productName`,
    COUNT(s.`id`) AS `sales`,
    CAST(SUM(s.`amountCents`) AS SIGNED) AS `revenueCents`,
    COALESCE(CAST(SUM(s.`amountCents`) AS SIGNED), 0) AS `revenueOrZero`
  FROM `products` p
  LEFT OUTER JOIN `sales` s ON p.`id` = s.`productId`
  GROUP BY p.`id`, p.`name`;

CREATE VIEW `v_sales_by_category` AS
  SELECT
    c.`name` AS `categoryName`,
    COUNT(s.`id`) AS `sales`,
    CAST(SUM(s.`amountCents`) AS SIGNED) AS `revenueCents`,
    MAX(s.`amountCents`) AS `maxCents`,
    COUNT(CASE WHEN s.`amountCents` >= 10000 THEN s.`id` END) AS `largeSales`
  FROM `sales` s
  INNER JOIN `products` p ON p.`id` = s.`productId`
  LEFT OUTER JOIN `categories` c ON c.`id` = p.`categoryId`
  GROUP BY c.`name`;

CREATE VIEW `v_sales_by_sku` AS
  SELECT
    p.`sku` AS `productSku`,
    COUNT(s.`id`) AS `sales`,
    CAST(SUM(s.`amountCents`) AS SIGNED) AS `revenueCents`
  FROM `sales` s
  INNER JOIN `products` p ON p.`id` = s.`productId`
  GROUP BY p.`sku`;

CREATE VIEW `v_product_refunds` AS
  SELECT
    p.`id` AS `productId`,
    p.`name` AS `productName`,
    COUNT(s.`id`) AS `sales`,
    MAX(s.`refunded`) AS `hasRefund`,
    COALESCE(MAX(s.`refunded`), 0) AS `hasRefundOrFalse`
  FROM `products` p
  LEFT OUTER JOIN `sales` s ON p.`id` = s.`productId`
  GROUP BY p.`id`, p.`name`;

CREATE VIEW `v_tickets_by_tags` AS
  SELECT
    t.`tags` AS `tags`,
    t.`attrs` AS `attrs`,
    COUNT(t.`id`) AS `tickets`
  FROM `tickets` t
  GROUP BY t.`tags`, t.`attrs`;

